package com.resurgeai.app

import android.app.Application
import android.content.Context
import com.resurgeai.core.data.di.WebClientId
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.android.HiltAndroidApp
import dagger.hilt.android.qualifiers.ApplicationContext
import dagger.hilt.components.SingletonComponent

@HiltAndroidApp
class ResurgeApplication : Application()

@Module
@InstallIn(SingletonComponent::class)
object AppModule {
    /** Generated by the google-services plugin from the OAuth "web" client in google-services.json. */
    @Provides
    @WebClientId
    fun webClientId(@ApplicationContext context: Context): String =
        context.getString(R.string.default_web_client_id)
}
